ON (Target.[SyncTableToScopeMapCommandGuid] = Source.[SyncTableToScopeMapCommandGuid])
WHEN MATCHED AND (Target.[SyncTableToScopeMapGuid] <> Source.[SyncTableToScopeMapGuid] 
					OR Target.[SelectIncrementalInserts] <> Source.[SelectIncrementalInserts]
					OR Target.[ApplyIncrementalInserts] <> Source.[ApplyIncrementalInserts]
					OR Target.[SelectIncrementalUpdates] <> Source.[SelectIncrementalUpdates]
					OR Target.[ApplyIncrementalUpdates] <> Source.[ApplyIncrementalUpdates]
					OR Target.[SelectIncrementalDeletes] <> Source.[SelectIncrementalDeletes]
					OR Target.[ApplyIncrementalDeletes] <> Source.[ApplyIncrementalDeletes]
					OR Target.[SelectUpdateConflicts] <> Source.[SelectUpdateConflicts]
					OR Target.[SelectDeleteConflicts] <> Source.[SelectDeleteConflicts]) THEN
	UPDATE SET 
				  [SyncTableToScopeMapGuid] = Source.[SyncTableToScopeMapGuid]
				, [SelectIncrementalInserts] = Source.[SelectIncrementalInserts]
				, [ApplyIncrementalInserts] = Source.[ApplyIncrementalInserts]
				, [SelectIncrementalUpdates] = Source.[SelectIncrementalUpdates]
				, [ApplyIncrementalUpdates] = Source.[ApplyIncrementalUpdates]
				, [SelectIncrementalDeletes] = Source.[SelectIncrementalDeletes]
				, [ApplyIncrementalDeletes] = Source.[ApplyIncrementalDeletes]
				, [SelectUpdateConflicts] = Source.[SelectUpdateConflicts]
				, [SelectDeleteConflicts] = Source.[SelectDeleteConflicts]
				, [CreatedDate] = Source.[CreatedDate]
				, [CreatedBy] =	Source.[CreatedBy]
				, [UpdatedDate] = Source.[UpdatedDate]
				, [UpdatedBy] =	Source.[UpdatedBy]
WHEN NOT MATCHED THEN
	INSERT ([SyncTableToScopeMapCommandGuid], [SyncTableToScopeMapGuid], [SelectIncrementalInserts], [ApplyIncrementalInserts], 
	[SelectIncrementalUpdates], [ApplyIncrementalUpdates], [SelectIncrementalDeletes], [ApplyIncrementalDeletes], [SelectUpdateConflicts], [SelectDeleteConflicts], 
	[CreatedDate], [CreatedBy], [UpdatedDate], [UpdatedBy])
		VALUES (Source.[SyncTableToScopeMapCommandGuid], Source.[SyncTableToScopeMapGuid], Source.[SelectIncrementalInserts], Source.[ApplyIncrementalInserts],
		Source.[SelectIncrementalUpdates], Source.[ApplyIncrementalUpdates], Source.[SelectIncrementalDeletes], Source.[ApplyIncrementalDeletes], Source.[SelectUpdateConflicts], Source.[SelectDeleteConflicts],
		Source.[CreatedDate],Source.[CreatedBy],Source.[UpdatedDate],Source.[UpdatedBy])
OUTPUT
	$action AS ActionType,
	deleted.[SyncTableToScopeMapCommandGuid], 
	inserted.[SyncTableToScopeMapCommandGuid], 
	deleted.[SyncTableToScopeMapGuid], 
	inserted.[SyncTableToScopeMapGuid], 
	deleted.[SelectIncrementalInserts], 
	inserted.[SelectIncrementalInserts], 
	deleted.[ApplyIncrementalInserts],
	inserted.[ApplyIncrementalInserts],
	deleted.[SelectIncrementalUpdates], 
	inserted.[SelectIncrementalUpdates], 
	deleted.[ApplyIncrementalUpdates], 
	inserted.[ApplyIncrementalUpdates], 
	deleted.[SelectIncrementalDeletes], 
	inserted.[SelectIncrementalDeletes], 
	deleted.[ApplyIncrementalDeletes], 
	inserted.[ApplyIncrementalDeletes], 
	deleted.[SelectUpdateConflicts], 
	inserted.[SelectUpdateConflicts], 
	deleted.[SelectDeleteConflicts],
	inserted.[SelectDeleteConflicts],
	deleted.[CreatedDate],
	inserted.[CreatedDate],
	deleted.[CreatedBy],
	inserted.[CreatedBy],
	deleted.[UpdatedDate],
	inserted.[UpdatedDate],
	deleted.[UpdatedBy],
	inserted.[UpdatedBy],
	deleted.[_ClusterIdx],
	inserted.[_ClusterIdx]
INTO @tblSyncTableToScopeMapCommandData;

SELECT @SyncTableToScopeMapCommandDataInserted = COUNT(*) FROM @tblSyncTableToScopeMapCommandData WHERE ActionType IN ( 'INSERT' );
SELECT @SyncTableToScopeMapCommandDataUpdated = COUNT(*) FROM @tblSyncTableToScopeMapCommandData WHERE ActionType IN ( 'UPDATE' )
SELECT @SyncTableToScopeMapCommandDataDeleted = COUNT(*) FROM @tblSyncTableToScopeMapCommandData WHERE ActionType IN ( 'DELETE' )

IF (@SyncTableToScopeMapCommandDataInserted > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @SyncTableToScopeMapCommandDataInserted) + ' NEW RECORDS INSERTED INTO [sync].[tblSyncTableToScopeMapCommand] **'
	PRINT ''
END

IF (@SyncTableToScopeMapCommandDataUpdated > 0)
BEGIN
	PRINT '** ' + CONVERT(NVARCHAR(25), @SyncTableToScopeMapCommandDataUpdated) + ' EXISTING RECORDS UPDATED IN [sync].[tblSyncTableToScopeMapCommand] **'
	PRINT ''
	SELECT * FROM @tblSyncTableToScopeMapCommandData WHERE ActionType IN ( 'UPDATE' );
END

SET NOCOUNT OFF

